parameters.jsCode:
// ---------------------------------------------------------------
// EDIT HERE: the retailers to compare, and the scraping proxy.
// ---------------------------------------------------------------

// Optional but strongly recommended. Amazon and Flipkart return a CAPTCHA
// page to datacenter IPs, so a direct fetch usually yields nothing usable.
//
// The key is read from the environment, never stored in this file, so this
// workflow is safe to commit and share. Set it before starting n8n:
//   cmd:         set SCRAPER_API_KEY=your_key
//   PowerShell:  $env:SCRAPER_API_KEY = 'your_key'
// Unset means fetch directly -- the smaller retailers still work.
const SCRAPER_API_KEY = (() => {
  try {
    return String($env.SCRAPER_API_KEY || '').trim();
  } catch (e) {
    // env access is off (N8N_BLOCK_ENV_ACCESS_IN_NODE=true)
    return '';
  }
})();

// Add or remove sites freely. {q} is replaced with the URL-encoded query.
const SITES = [
  { site: 'Amazon.in',         url: 'https://www.amazon.in/s?k={q}' },
  { site: 'Flipkart',          url: 'https://www.flipkart.com/search?q={q}' },
  { site: 'Croma',             url: 'https://www.croma.com/searchB?q={q}%3Arelevance' },
  { site: 'Reliance Digital',  url: 'https://www.reliancedigital.in/search?q={q}%3Arelevance' },
  { site: 'Vijay Sales',       url: 'https://www.vijaysales.com/search/{q}' },
];

// ---------------------------------------------------------------

const form = $input.first().json;
const query = String(form.Product || '').trim();
if (!query) {
  throw new Error('No product was submitted.');
}

const encoded = encodeURIComponent(query);

return SITES.map((s) => {
  const searchUrl = s.url.replace('{q}', encoded);

  // Route through the proxy when a key is present, otherwise go direct.
  // render=true executes JavaScript, which Flipkart and Croma need.
  const fetchUrl = SCRAPER_API_KEY
    ? 'https://api.scraperapi.com/?api_key=' +
      SCRAPER_API_KEY +
      '&country_code=in&render=true&url=' +
      encodeURIComponent(searchUrl)
    : searchUrl;

  return {
    json: {
      site: s.site,
      query,
      budget: form.Budget || null,
      preferences: form.Preferences || '',
      searchUrl,
      fetchUrl,
      viaProxy: Boolean(SCRAPER_API_KEY),
    },
  };
});

// Strip each page down to plain text so the model reads content, not markup.
// This is deliberately dumb -- no CSS selectors to break when a site redesigns.
const sites = $('Prepare Site Requests').all();
const responses = $input.all();

const MAX_CHARS = 12000;

const out = [];
for (let i = 0; i < responses.length; i++) {
  const meta = sites[i] ? sites[i].json : {};
  const body = responses[i].json;

  if (body.error || !body.html) {
    out.push({
      json: {
        site: meta.site,
        searchUrl: meta.searchUrl,
        ok: false,
        reason: 'request failed (blocked, timed out, or refused)',
        text: '',
      },
    });
    continue;
  }

  const text = String(body.html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&#8377;|&#x20B9;|&rupee;/gi, 'Rs.')
    .replace(/\s+/g, ' ')
    .trim();

  const looksBlocked =
    /captcha|are you a robot|unusual traffic|access denied|enable javascript to continue/i.test(
      text.slice(0, 3000)
    ) || text.length < 500;

  out.push({
    json: {
      site: meta.site,
      searchUrl: meta.searchUrl,
      ok: !looksBlocked,
      reason: looksBlocked ? 'page was blocked, empty, or JS-only' : '',
      text: text.slice(0, MAX_CHARS),
    },
  });
}

return out;

