// Fold the five per-site extractions into one payload for the judging step.
const pages = $('HTML to Text').all();
const results = $input.all();
const form = $('Prepare Site Requests').first().json;

const offers = [];
for (let i = 0; i < results.length; i++) {
  const page = pages[i] ? pages[i].json : {};

  let parsed = results[i].json.output;
  if (typeof parsed === 'string') {
    try {
      parsed = JSON.parse(parsed);
    } catch (e) {
      parsed = null;
    }
  }

  offers.push({
    site: page.site,
    searchUrl: page.searchUrl,
    fetched: Boolean(page.ok),
    fetchNote: page.reason || '',
    found: Boolean(parsed && parsed.found),
    note: (parsed && parsed.note) || '',
    products: (parsed && Array.isArray(parsed.products) ? parsed.products : []).filter(
      (p) => p && typeof p.price === 'number' && p.price > 0
    ),
  });
}

const withPrices = offers.filter((o) => o.products.length > 0);

return [
  {
    json: {
      query: form.query,
      budget: form.budget,
      preferences: form.preferences,
      viaProxy: form.viaProxy,
      sitesChecked: offers.length,
      sitesWithPrices: withPrices.length,
      offers,
      comparedAt: new Date().toISOString(),
    },
  },
];

