parameters.jsCode:
// Turn the verdict into the page the shopper sees when the form completes.
const ctx = $('Collect Offers').first().json;

let v = $input.first().json.output;
if (typeof v === 'string') {
  try {
    v = JSON.parse(v);
  } catch (e) {
    v = null;
  }
}
if (!v) {
  return [
    {
      json: {
        title: 'Could not compare',
        html: '<p>The retailers did not return usable data this time. Try a more specific product name, or add a scraping proxy key in the <b>Prepare Site Requests</b> node.</p>',
      },
    },
  ];
}

const esc = (x) =>
  String(x == null ? '' : x)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const rupees = (n) =>
  typeof n === 'number' ? 'Rs. ' + n.toLocaleString('en-IN') : 'not listed';

const urlFor = (site) => {
  const hit = ctx.offers.find((o) => o.site === site);
  return hit ? hit.searchUrl : '';
};

const confColor =
  v.confidence === 'high' ? '#137333' : v.confidence === 'medium' ? '#b06000' : '#c5221f';

const rows = (v.ranking || [])
  .map((r, i) => {
    const link = urlFor(r.site);
    const name = link
      ? '<a href="' + esc(link) + '" style="color:#1a56db;text-decoration:none;">' + esc(r.site) + '</a>'
      : esc(r.site);
    const bg = i === 0 ? 'background:#e8f5e9;' : '';
    return (
      '<tr style="' + bg + '">' +
      '<td style="padding:10px 12px;border-bottom:1px solid #e8eaed;font-weight:600;">' + name + '</td>' +
      '<td style="padding:10px 12px;border-bottom:1px solid #e8eaed;white-space:nowrap;font-weight:600;">' + rupees(r.price) + '</td>' +
      '<td style="padding:10px 12px;border-bottom:1px solid #e8eaed;font-size:13px;color:#3c4043;">' + esc(r.product) +
      (r.note ? '<div style="color:#5f6368;font-size:12px;margin-top:3px;">' + esc(r.note) + '</div>' : '') +
      '</td></tr>'
    );
  })
  .join('');

const warnings = (v.warnings || []).length
  ? '<div style="background:#fef7e0;border-left:3px solid #f9ab00;padding:10px 14px;margin:16px 0;border-radius:4px;">' +
    '<div style="font-weight:600;font-size:13px;margin-bottom:4px;">Worth checking</div>' +
    '<ul style="margin:0;padding-left:18px;font-size:13px;color:#3c4043;">' +
    v.warnings.map((w) => '<li>' + esc(w) + '</li>').join('') +
    '</ul></div>'
  : '';

const missing = (v.noDataFrom || []).length
  ? '<p style="font-size:12px;color:#5f6368;margin-top:14px;">No usable data from: ' +
    v.noDataFrom.map(esc).join(', ') +
    '. This comparison is partial.</p>'
  : '';

const budgetLine =
  v.withinBudget === null || v.withinBudget === undefined
    ? ''
    : '<p style="font-size:13px;color:' + (v.withinBudget ? '#137333' : '#c5221f') + ';margin:6px 0 0;">' +
      (v.withinBudget ? 'Within your budget.' : 'Over your budget.') +
      '</p>';

const html =
  '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;max-width:680px;">' +
  '<div style="background:#f1f3f4;border-radius:8px;padding:16px;margin-bottom:6px;">' +
  '<div style="font-size:13px;color:#5f6368;">Best place to buy</div>' +
  '<div style="font-size:22px;font-weight:700;margin:4px 0;">' + esc(v.bestSite) + ' &mdash; ' + rupees(v.bestPrice) + '</div>' +
  '<div style="font-size:14px;color:#3c4043;">' + esc(v.bestProduct) + '</div>' +
  budgetLine +
  '</div>' +
  '<p style="font-size:15px;line-height:1.55;color:#202124;">' + esc(v.verdict) + '</p>' +
  warnings +
  '<table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:14px;">' +
  '<thead><tr style="text-align:left;color:#5f6368;font-size:12px;text-transform:uppercase;">' +
  '<th style="padding:6px 12px;">Retailer</th><th style="padding:6px 12px;">Price</th><th style="padding:6px 12px;">Listing</th>' +
  '</tr></thead><tbody>' + rows + '</tbody></table>' +
  missing +
  '<p style="font-size:12px;color:#80868b;margin-top:16px;">' +
  'Checked ' + ctx.sitesChecked + ' retailers, ' + ctx.sitesWithPrices + ' returned prices. ' +
  'Confidence: <span style="color:' + confColor + ';font-weight:600;">' + esc(v.confidence) + '</span>. ' +
  'Prices change constantly &mdash; confirm on the retailer page before paying.</p>' +
  '</div>';

return [{ json: { title: 'Results for "' + ctx.query + '"', html, verdict: v } }];
